@Test
public void sortTest() {
    DocumentationViewer docViewer = new DocumentationViewer();
    Map<UriRef, DocumentationViewer.DocumentationItem> uri2docItemObj = new HashMap<UriRef, DocumentationViewer.DocumentationItem>();
    UriRef ref1 = new UriRef("ref1");
    UriRef ref2 = new UriRef("ref2");
    UriRef ref3 = new UriRef("ref3");
    UriRef ref4 = new UriRef("ref4");
    UriRef ref5 = new UriRef("ref5");
    Set<UriRef> set1 = new HashSet<UriRef>();
    DocumentationViewer.DocumentationItem a = new DocumentationViewer.DocumentationItem(ref1, set1, uri2docItemObj);
    Set<UriRef> set2 = new HashSet<UriRef>();
    set2.add(ref1);
    DocumentationViewer.DocumentationItem b = new DocumentationViewer.DocumentationItem(ref2, set2, uri2docItemObj);
    Set<UriRef> set3 = new HashSet<UriRef>();
    set3.add(ref2);
    DocumentationViewer.DocumentationItem c = new DocumentationViewer.DocumentationItem(ref3, set3, uri2docItemObj);
    Set<UriRef> set4 = new HashSet<UriRef>();
    set4.add(ref3);
    DocumentationViewer.DocumentationItem d = new DocumentationViewer.DocumentationItem(ref4, set4, uri2docItemObj);
    Set<UriRef> set5 = new HashSet<UriRef>();
    set5.add(ref4);
    DocumentationViewer.DocumentationItem e = new DocumentationViewer.DocumentationItem(ref5, set5, uri2docItemObj);
    uri2docItemObj.put(ref2, b);
    uri2docItemObj.put(ref4, d);
    uri2docItemObj.put(ref1, a);
    uri2docItemObj.put(ref3, c);
    uri2docItemObj.put(ref5, e);
    List<DocumentationViewer.DocumentationItem> orderedList = docViewer.sortDocItems(uri2docItemObj.values());
    Iterator<DocumentationViewer.DocumentationItem> iter = orderedList.iterator();
    Object[] expecteds = new DocumentationViewer.DocumentationItem[5];
    expecteds[0] = a;
    expecteds[1] = b;
    expecteds[2] = c;
    expecteds[3] = d;
    expecteds[4] = e;
    Assert.assertArrayEquals(expecteds, orderedList.toArray());
}

