" + "<area/>
" + "<base/>
" + "<basefont/>
" + "<br/>
" + "<hr/>
" + "<input/>
" + "<img/>
" + "<link/>
" + "<meta/>
" + "<body>
" + "hello" + "</body>
" + "</html>";
    final String expectedHtml = "<html>
" + "<script></script>
" + "<test ></test>
" + "<foo id="bla" ></foo>
" + "<area/>
" + "<base/>
" + "<basefont/>
" + "<br/>
" + "<hr/>
" + "<input/>
" + "<img/>
" + "<link/>
" + "<meta/>
" + "<body>
" + "hello" + "</body>
" + "</html>";
    final ByteArrayOutputStream baos = new ByteArrayOutputStream();
    final WritableByteChannel channel = new SelfClosing2ClosingTagsByteChannel(Channels.newChannel(baos), new ResponseStatusInfo() {

        @Override
        public boolean convertXhtml2Html() {
            return true;
        }
    });
    int bytesWritten = channel.write(ByteBuffer.wrap(someHtml.getBytes(UTF8)));
    Assert.assertEquals(someHtml.length(), bytesWritten);
