@Test
public void testGraphIsNotMutable() throws Exception {
    Triple t1 = createTestTriple();
    Set<Triple> t = new HashSet<Triple>();
    t.add(t1);
    TcProvider provider = getInstance();
    Graph graph = provider.createGraph(graphUriRef, createTestTripleCollection(t1));
    boolean expThrown = false;
    try {
        graph.add(t1);
    } catch (UnsupportedOperationException uoe) {
        expThrown = true;
    }
    assertTrue(expThrown);
    expThrown = false;
    try {
        graph.remove(t1);
    } catch (UnsupportedOperationException uoe) {
        expThrown = true;
    }
    assertTrue(expThrown);
    expThrown = false;
    try {
        graph.addAll(t);
    } catch (UnsupportedOperationException uoe) {
        expThrown = true;
    }
    assertTrue(expThrown);
    expThrown = false;
    try {
        graph.clear();
    } catch (UnsupportedOperationException uoe) {
        expThrown = true;
    }
    assertTrue(expThrown);
    expThrown = false;
    try {
        graph.removeAll(t);
    } catch (UnsupportedOperationException uoe) {
        expThrown = true;
    }
    assertTrue(expThrown);
}

