        for (Entry<String, Integer> facet : facets) {
            if (old == facet.getValue() && oldKey != null && (facet.getKey().compareTo(oldKey) < 0)) {
                Assert.fail("Facet keys are not ordered in ascending order.");
            }
            if (facet.getValue() < old) {
